// The game engine: physics, collisions, enemies, items, camera, drawing.
// Coding agents: do NOT edit this file. Game content lives in config.js and levels.js.

import { TILE, drawText, textWidth, buildTiles, itemSprite, blob, mountain, decoration, building } from './art.js'
import { loadCharacters } from './characters.js'
import { LEVELS, ROWS } from './levels.js'
import { Audio } from './audio.js'
import config from './config.js'

export const VIEW_W = 400
export const VIEW_H = 224

const STEP = 1000 / 60
const SOLID = new Set(['#', 'B', '?', 'P', 'U', 'S', '[', ']', '{', '}'])

// Movement tuning (pixels per frame at 60 fps)
const WALK_MAX = 1.75
const RUN_MAX = 2.8
const ACCEL = 0.075
const RUN_ACCEL = 0.1
const AIR_ACCEL = 0.07
const FRICTION = 0.11
const SKID = 0.22
const JUMP_V = 6.2
const JUMP_SPEED_BONUS = 0.25
const GRAVITY_HOLD = 0.28
const GRAVITY = 0.72
const MAX_FALL = 6.5
const COYOTE = 6
const JUMP_BUFFER = 7

const KEYS = {
  left: ['ArrowLeft', 'KeyA'],
  right: ['ArrowRight', 'KeyD'],
  jump: ['Space', 'KeyZ', 'ArrowUp', 'KeyW', 'KeyK'],
  run: ['ShiftLeft', 'ShiftRight', 'KeyX', 'KeyJ'],
  start: ['Enter', 'NumpadEnter'],
  pause: ['KeyP', 'Escape'],
  mute: ['KeyM'],
}
export const GAME_KEYS = new Set(Object.values(KEYS).flat())

const overlap = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y
const upper = (s) => String(s ?? '').toUpperCase()

export class Game {
  constructor(canvas, callbacks = {}) {
    this.canvas = canvas
    canvas.width = VIEW_W
    canvas.height = VIEW_H
    this.g = canvas.getContext('2d')
    this.g.imageSmoothingEnabled = false
    this.cb = callbacks
    this.audio = new Audio()
    this.down = new Set()
    this.prevDown = new Set()
    this.frame = 0
    this.state = 'loading'
    this.levelIndex = 0
    this.buildArt()
    this.acc = 0
    this.last = performance.now()
    this.loop = this.loop.bind(this)
    this.raf = requestAnimationFrame(this.loop)

    const specs = { player: config.player }
    for (const [k, v] of Object.entries(config.enemies)) specs[k] = v
    loadCharacters(specs).then((chars) => {
      this.chars = chars
      this.loadLevel(0, false)
      this.state = 'title'
    })
  }

  destroy() {
    cancelAnimationFrame(this.raf)
    this.audio.stopMusic()
  }

  buildArt() {
    const c = config
    this.coinImg = itemSprite(c.collectible.shape, c.collectible.colors)
    this.powerImg = itemSprite(c.powerUp.shape, c.powerUp.colors)
    this.themeArt = c.themes.map((t, i) => {
      const art = { tiles: buildTiles(t, this.coinImg, 7 + i * 31), deco: decoration(t.decoration, t.decorationColors) }
      if (t.background === 'hills') {
        art.cloud = blob(46, 26, [[12, 16, 9], [23, 11, 10], [34, 16, 9], [22, 18, 8]], '#ffffff', '#c7dff0', '#e3f1fb')
        art.hillBig = blob(112, 50, [[56, 56, 54]], t.far[0], t.far[1], null)
        art.hillSmall = blob(70, 30, [[35, 36, 34]], t.near[0], t.near[1], null)
      } else if (t.background === 'cave') {
        art.rock = blob(60, 40, [[20, 0, 18], [42, 0, 16]], t.far[0], t.far[1], null)
      } else {
        art.far = mountain(160, 90, t.far[0], t.far[1], 3)
        art.near = mountain(140, 70, t.near[0], t.near[1], 9)
        art.sun = t.background === 'night'
          ? blob(24, 24, [[12, 12, 10]], '#f4f1de', '#c9c4a8', null)
          : blob(40, 40, [[20, 20, 18]], '#ffd27a', '#ffb347', null)
        if (t.background === 'night') {
          const r = (n) => ((Math.sin(n * 12.9898) * 43758.5453) % 1 + 1) % 1
          art.stars = Array.from({ length: 70 }, (_, n) => [Math.floor(r(n) * 600), Math.floor(r(n + 99) * 130), r(n + 7) > 0.8])
        }
      }
      return art
    })
    this.house = building(c.goal.building)
  }

  // ---------- input ----------
  setKey(code, isDown) {
    if (isDown) {
      this.down.add(code)
      this.audio.unlock()
    } else this.down.delete(code)
  }
  clearKeys() {
    this.down.clear()
  }
  held(action) {
    return KEYS[action].some((k) => this.down.has(k))
  }
  pressed(action) {
    return KEYS[action].some((k) => this.down.has(k) && !this.prevDown.has(k))
  }

  // ---------- flow ----------
  toTitle() {
    this.state = 'title'
    this.audio.stopMusic()
    this.loadLevel(0, false)
  }

  newGame() {
    this.score = 0
    this.coins = 0
    this.lives = 3
    this.levelIndex = 0
    this.powered = false
    this.checkpointReached = false
    this.startIntro()
  }

  startIntro() {
    this.state = 'intro'
    this.timer = 150
    this.audio.stopMusic()
  }

  get themeIndex() {
    return Math.min(LEVELS[this.levelIndex].theme ?? this.levelIndex, config.themes.length - 1)
  }

  loadLevel(index, useCheckpoint) {
    const def = LEVELS[index]
    const L = def.build()
    this.levelIndex = index
    this.level = L
    this.theme = config.themes[this.themeIndex]
    this.art = this.themeArt[this.themeIndex]
    this.tiles = L.tiles.map((r) => [...r])
    this.widthPx = L.width * TILE
    this.enemies = []
    this.items = []
    this.particles = []
    this.popups = []
    this.bumps = []
    const startTile = useCheckpoint && L.checkpoint ? { x: L.checkpoint, y: 11 } : L.start
    for (const e of L.entities) {
      if (e.type === 'coin') this.items.push({ type: 'coin', x: e.x * TILE + 3, y: e.y * TILE + 3, w: 10, h: 10 })
      else if (e.type === 'enemy' && config.enemies[e.kind]) {
        // don't spawn pests right on top of a respawning player
        if (Math.abs(e.x - startTile.x) < 7 && e.x >= startTile.x) continue
        this.spawnEnemy(e.kind, e.x, e.y)
      }
    }
    const pc = this.chars.player
    this.player = {
      x: startTile.x * TILE + (TILE - pc.hitW) / 2, y: (startTile.y + 1) * TILE - pc.hitH, w: pc.hitW, h: pc.hitH,
      vx: 0, vy: 0, dir: 1, onGround: false, coyote: 0, buffer: 0, inv: 0, anim: 0, combo: 0, powered: false,
    }
    this.flagY = 2 * TILE + 4
    this.time = 300
    this.timeFrames = 0
    this.camX = 0
    this.updateCamera(true)
  }

  spawnEnemy(kind, tx, ty) {
    const def = config.enemies[kind]
    const ch = this.chars[kind]
    const w = ch.hitW
    const h = ch.hitH
    this.enemies.push({
      kind, def, ch, w, h, x: tx * TILE + (TILE - w) / 2, y: (ty + 1) * TILE - h, baseY: (ty + 1) * TILE - h,
      vx: 0, vy: 0, active: false, state: 'alive', t: 0, onGround: false, speed: def.speed ?? 0.5,
    })
  }

  // ---------- main loop ----------
  loop(now) {
    this.acc += Math.min(now - this.last, 100)
    this.last = now
    while (this.acc >= STEP) {
      this.update()
      this.prevDown = new Set(this.down)
      this.acc -= STEP
    }
    this.render()
    this.raf = requestAnimationFrame(this.loop)
  }

  update() {
    this.frame++
    if (this.pressed('mute')) this.audio.toggleMute()
    switch (this.state) {
      case 'loading':
        break
      case 'title':
        if (this.pressed('start') || this.pressed('jump')) this.newGame()
        break
      case 'intro':
        if (--this.timer <= 0) {
          this.loadLevel(this.levelIndex, this.checkpointReached)
          this.player.powered = this.powered
          this.state = 'play'
          this.audio.startMusic(this.theme.music ?? this.levelIndex)
        }
        break
      case 'play':
        if (this.pressed('pause') || this.pressed('start')) {
          this.state = 'paused'
          this.audio.stopMusic()
          this.audio.play('pause')
          break
        }
        this.updatePlay()
        break
      case 'paused':
        if (this.pressed('pause') || this.pressed('start')) {
          this.state = 'play'
          this.audio.play('pause')
          this.audio.startMusic(this.theme.music ?? this.levelIndex)
        }
        break
      case 'dying':
        this.updateDying()
        break
      case 'flag':
        this.updateFlag()
        break
      case 'clear':
        this.updateClear()
        break
      case 'gameover':
        if (this.timer > 0) this.timer--
        else if (this.pressed('start')) this.toTitle()
        break
      case 'win':
        this.updateParticles()
        if (this.frame % 20 === 0) this.fireworks()
        if (this.timer > 0) this.timer--
        else if (this.pressed('start')) this.toTitle()
        break
      default:
        break
    }
  }

  updatePlay() {
    const p = this.player
    this.updatePlayer()
    if (this.state !== 'play') return
    this.updateEnemies()
    this.updateItems()
    this.updateParticles()
    this.updateCamera(false)
    if (this.level.checkpoint && p.x > this.level.checkpoint * TILE) this.checkpointReached = true
    if (++this.timeFrames >= 40) {
      this.timeFrames = 0
      this.time--
      if (this.time === 100) this.popup(p.x, p.y - 10, 'HURRY!')
      if (this.time <= 0) this.die()
    }
    if (p.inv > 0) p.inv--
    const poleLeft = this.level.flagX * TILE
    if (p.x + p.w >= poleLeft && p.x < poleLeft + 10 && p.y < 12 * TILE) this.grabFlag()
  }

  // ---------- player ----------
  updatePlayer() {
    const p = this.player
    const left = this.held('left')
    const right = this.held('right')
    const run = this.held('run')
    const max = run ? RUN_MAX : WALK_MAX
    const dir = left && !right ? -1 : right && !left ? 1 : 0
    if (dir !== 0) {
      p.dir = dir
      if (p.onGround && p.vx !== 0 && Math.sign(p.vx) !== dir) p.vx += dir * SKID
      else p.vx += dir * (p.onGround ? (run ? RUN_ACCEL : ACCEL) : AIR_ACCEL)
      if (Math.abs(p.vx) > max) p.vx -= Math.sign(p.vx) * Math.min(Math.abs(p.vx) - max, p.onGround ? 0.1 : 0.03)
    } else if (p.onGround) {
      p.vx = Math.abs(p.vx) <= FRICTION ? 0 : p.vx - Math.sign(p.vx) * FRICTION
    }
    if (this.pressed('jump')) p.buffer = JUMP_BUFFER
    else if (p.buffer > 0) p.buffer--
    if (p.onGround) {
      p.coyote = COYOTE
      p.combo = 0
    } else if (p.coyote > 0) p.coyote--
    if (p.buffer > 0 && p.coyote > 0) {
      p.vy = -(JUMP_V + Math.abs(p.vx) * JUMP_SPEED_BONUS)
      p.onGround = false
      p.coyote = 0
      p.buffer = 0
      this.audio.play('jump')
    }
    p.vy = Math.min(p.vy + (p.vy < 0 && this.held('jump') ? GRAVITY_HOLD : GRAVITY), MAX_FALL)
    this.moveX(p)
    this.moveY(p, true)
    if (p.x < this.camX) {
      p.x = this.camX
      if (p.vx < 0) p.vx = 0
    }
    p.anim += Math.abs(p.vx) * 0.12
    if (p.y > ROWS * TILE + 8) this.die()
  }

  // ---------- tile collision ----------
  tileAt(tx, ty) {
    if (ty < 0 || ty >= ROWS) return '.'
    if (tx < 0 || tx >= this.level.width) return 'S'
    return this.tiles[ty][tx]
  }
  solid(tx, ty) {
    return SOLID.has(this.tileAt(tx, ty))
  }

  moveX(o) {
    o.x += o.vx
    const y0 = Math.floor(o.y / TILE)
    const y1 = Math.floor((o.y + o.h - 0.01) / TILE)
    if (o.vx > 0) {
      const tx = Math.floor((o.x + o.w) / TILE)
      for (let ty = y0; ty <= y1; ty++) {
        if (this.solid(tx, ty)) {
          o.x = tx * TILE - o.w
          o.vx = 0
          return true
        }
      }
    } else if (o.vx < 0) {
      const tx = Math.floor(o.x / TILE)
      for (let ty = y0; ty <= y1; ty++) {
        if (this.solid(tx, ty)) {
          o.x = (tx + 1) * TILE
          o.vx = 0
          return true
        }
      }
    }
    return false
  }

  moveY(o, isPlayer) {
    o.y += o.vy
    o.onGround = false
    const x0 = Math.floor(o.x / TILE)
    const x1 = Math.floor((o.x + o.w - 0.01) / TILE)
    if (o.vy > 0) {
      const ty = Math.floor((o.y + o.h) / TILE)
      for (let tx = x0; tx <= x1; tx++) {
        if (this.solid(tx, ty)) {
          o.y = ty * TILE - o.h
          o.vy = 0
          o.onGround = true
          return
        }
      }
    } else if (o.vy < 0) {
      const ty = Math.floor(o.y / TILE)
      const hits = []
      for (let tx = x0; tx <= x1; tx++) if (this.solid(tx, ty)) hits.push(tx)
      if (!hits.length) return
      if (isPlayer && hits.length === 1) {
        const tx = hits[0]
        const overRight = o.x + o.w - tx * TILE
        const overLeft = (tx + 1) * TILE - o.x
        if (overRight <= 4 && !this.solid(tx - 1, ty)) {
          o.x = tx * TILE - o.w
          return
        }
        if (overLeft <= 4 && !this.solid(tx + 1, ty)) {
          o.x = (tx + 1) * TILE
          return
        }
      }
      o.y = (ty + 1) * TILE
      o.vy = 1
      if (isPlayer) {
        const center = o.x + o.w / 2
        const tx = hits.reduce((best, t) => (Math.abs(t * TILE + 8 - center) < Math.abs(best * TILE + 8 - center) ? t : best))
        this.hitBlock(tx, ty)
      }
    }
  }

  hitBlock(tx, ty) {
    const t = this.tileAt(tx, ty)
    const p = this.player
    if (t === '?') {
      this.tiles[ty][tx] = 'U'
      this.bump(tx, ty)
      this.particles.push({ type: 'popcoin', x: tx * TILE + 3, y: ty * TILE - 10, vy: -4.5, t: 0 })
      this.collectCoin(tx * TILE + 8, ty * TILE - 20)
    } else if (t === 'P') {
      this.tiles[ty][tx] = 'U'
      this.bump(tx, ty)
      this.items.push({ type: 'power', x: tx * TILE + 3, y: ty * TILE, w: 10, h: 10, vx: 0, vy: 0, rise: 26, dir: 1 })
      this.audio.play('sprout')
    } else if (t === 'B') {
      if (p.powered) {
        this.tiles[ty][tx] = '.'
        this.addScore(50)
        this.audio.play('break')
        for (const [dx, dy, vx, vy] of [[0, 0, -1.2, -5], [8, 0, 1.2, -5], [0, 8, -1.2, -3.5], [8, 8, 1.2, -3.5]]) {
          this.particles.push({ type: 'debris', x: tx * TILE + dx, y: ty * TILE + dy, vx, vy, t: 0 })
        }
        this.killOnTile(tx, ty)
      } else {
        this.bump(tx, ty)
        this.audio.play('bump')
      }
    } else this.audio.play('bump')
  }

  bump(tx, ty) {
    this.bumps.push({ tx, ty, t: 0 })
    this.killOnTile(tx, ty)
  }

  killOnTile(tx, ty) {
    const top = ty * TILE
    const zone = { x: tx * TILE - 2, y: top - 4, w: TILE + 4, h: 5 }
    for (const e of this.enemies) if (e.state === 'alive' && overlap(e, zone)) this.flipEnemy(e, 200)
    for (const it of this.items) {
      if (it.type === 'coin' && overlap(it, { x: tx * TILE, y: top - 16, w: TILE, h: 16 })) {
        it.dead = true
        this.collectCoin(it.x + 5, it.y)
      }
    }
  }

  // ---------- enemies ----------
  updateEnemies() {
    const p = this.player
    for (const e of this.enemies) {
      if (!e.active) {
        if (e.x < this.camX + VIEW_W + 24) {
          e.active = true
          e.vx = -e.speed
        } else continue
      }
      e.t++
      if (e.state === 'squashed') {
        if (e.t > 30) e.dead = true
        continue
      }
      if (e.state === 'flipped') {
        e.vy += 0.35
        e.x += e.vx
        e.y += e.vy
        if (e.y > ROWS * TILE + 32) e.dead = true
        continue
      }
      const behavior = e.def.behavior
      if (behavior === 'fly') {
        e.x += e.vx
        e.y = e.baseY + Math.sin(e.t * 0.045) * 22
      } else {
        if (behavior === 'hop' && e.onGround && e.t % 110 === 0) e.vy = -4.6
        e.vy = Math.min(e.vy + 0.4, 6)
        const before = e.vx
        if (this.moveX(e)) e.vx = -before
        this.moveY(e, false)
        if (e.y > ROWS * TILE + 16) e.dead = true
      }
      if (e.x < this.camX - 64) e.dead = true
      for (const o of this.enemies) {
        if (o !== e && o.active && o.state === 'alive' && behavior !== 'fly' && o.def.behavior !== 'fly' && overlap(e, o)) {
          if ((e.vx > 0 && e.x < o.x) || (e.vx < 0 && e.x > o.x)) e.vx = -e.vx
        }
      }
      if (this.state !== 'play' || !overlap(p, e)) continue
      const falling = p.vy > 0 && p.y + p.h - e.y < 10
      if (falling && e.def.stompable !== false) {
        e.state = 'squashed'
        e.t = 0
        p.vy = this.held('jump') ? -6.6 : -4.2
        p.combo++
        const pts = [100, 200, 400, 800, 1000, 2000, 4000, 8000][Math.min(p.combo - 1, 7)]
        this.addScore(pts, e.x + e.w / 2, e.y - 6)
        this.audio.play('stomp')
      } else if (p.inv === 0) this.hurt()
    }
    this.enemies = this.enemies.filter((e) => !e.dead)
  }

  flipEnemy(e, pts) {
    e.state = 'flipped'
    e.vy = -4
    e.vx = e.x < this.player.x ? -0.8 : 0.8
    this.addScore(pts, e.x + e.w / 2, e.y - 6)
    this.audio.play('stomp')
  }

  // ---------- items ----------
  updateItems() {
    const p = this.player
    for (const it of this.items) {
      if (it.type === 'power') {
        if (it.rise > 0) {
          it.rise--
          it.y -= 0.6
          continue
        }
        it.vx = 1.0 * it.dir
        it.vy = Math.min(it.vy + 0.4, 6)
        if (this.moveX(it)) it.dir = -it.dir
        this.moveY(it, false)
        if (it.y > ROWS * TILE) it.dead = true
      }
      if (overlap(p, it)) {
        it.dead = true
        if (it.type === 'coin') this.collectCoin(it.x + 5, it.y)
        else this.powerUp()
      }
    }
    this.items = this.items.filter((i) => !i.dead)
  }

  collectCoin(x, y) {
    this.coins++
    this.addScore(200, x, y)
    this.audio.play('leaf')
    if (this.coins % 100 === 0) {
      this.lives++
      this.popup(this.player.x, this.player.y - 12, '1UP')
      this.audio.play('oneup')
    }
  }

  powerUp() {
    const p = this.player
    this.addScore(1000, p.x + 5, p.y - 8)
    if (!p.powered) {
      p.powered = true
      this.powered = true
      this.flash = 40
    }
    this.audio.play('power')
  }

  hurt() {
    const p = this.player
    if (p.powered) {
      p.powered = false
      this.powered = false
      p.inv = 120
      this.audio.play('shrink')
    } else this.die()
  }

  die() {
    if (this.state !== 'play') return
    const p = this.player
    this.state = 'dying'
    this.timer = 170
    p.vx = 0
    p.vy = -5.5
    p.powered = false
    this.powered = false
    this.audio.stopMusic()
    this.audio.play('die')
  }

  updateDying() {
    const p = this.player
    this.timer--
    if (this.timer < 140) {
      p.vy = Math.min(p.vy + 0.3, 6)
      p.y += p.vy
    }
    if (this.timer <= 0) {
      this.lives--
      if (this.lives <= 0) {
        this.state = 'gameover'
        this.timer = 90
        this.audio.play('gameover')
        this.cb.onEnd?.('gameover', this.score, this.levelIndex + 1)
      } else this.startIntro()
    }
  }

  // ---------- end of level ----------
  grabFlag() {
    const p = this.player
    this.state = 'flag'
    this.audio.stopMusic()
    this.audio.play('flag')
    const height = 11 * TILE - (p.y + p.h)
    const pts = height > 120 ? 5000 : height > 90 ? 2000 : height > 60 ? 800 : height > 30 ? 400 : 100
    this.addScore(pts, p.x + 10, p.y)
    p.x = this.level.flagX * TILE + 8 - p.w
    p.vx = 0
    p.vy = 0
    p.dir = 1
    this.timer = 0
  }

  updateFlag() {
    const p = this.player
    const bottom = 11 * TILE
    if (this.flagY < bottom - 14) this.flagY += 2.5
    if (p.y + p.h < bottom) p.y = Math.min(p.y + 2.5, bottom - p.h)
    else if (this.flagY >= bottom - 14 && ++this.timer > 20) {
      this.state = 'clear'
      p.x += 10
      this.timer = 0
    }
    this.updateParticles()
  }

  updateClear() {
    const p = this.player
    const door = this.level.houseX * TILE + 40
    this.updateParticles()
    if (!p.hidden) {
      p.vx = 1.1
      p.vy = Math.min(p.vy + GRAVITY, MAX_FALL)
      this.moveX(p)
      this.moveY(p)
      p.anim += 0.15
      this.updateCamera(false)
      if (p.x + p.w / 2 >= door) {
        p.hidden = true
        this.timer = 0
      }
      return
    }
    if (this.time > 0) {
      const n = Math.min(this.time, 3)
      this.time -= n
      this.addScore(50 * n)
      if (this.frame % 3 === 0) this.audio.play('tick')
      return
    }
    if (++this.timer > 90) {
      this.checkpointReached = false
      if (this.levelIndex + 1 < LEVELS.length) {
        this.levelIndex++
        this.startIntro()
      } else {
        this.state = 'win'
        this.timer = 60
        this.audio.play('oneup')
        this.cb.onEnd?.('win', this.score, LEVELS.length)
      }
    }
  }

  fireworks() {
    const x = 60 + Math.random() * (VIEW_W - 120)
    const y = 30 + Math.random() * 70
    const colors = [config.collectible.colors.light, config.powerUp.colors.light, config.goal.flag, '#9be564', '#7ee0b0']
    const col = colors[Math.floor(Math.random() * colors.length)]
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * Math.PI * 2
      this.particles.push({ type: 'spark', x, y, vx: Math.cos(a) * 1.6, vy: Math.sin(a) * 1.6, t: 0, col, screen: true })
    }
    this.audio.play('stomp')
  }

  // ---------- effects ----------
  addScore(pts, x, y) {
    this.score += pts
    if (x !== undefined) this.popup(x, y, String(pts))
  }
  popup(x, y, text) {
    this.popups.push({ x, y, text, t: 0 })
  }

  updateParticles() {
    for (const q of this.particles) {
      q.t++
      if (q.type === 'popcoin') {
        q.y += q.vy
        q.vy += 0.3
        if (q.t > 28) q.dead = true
      } else {
        q.x += q.vx
        q.y += q.vy
        q.vy += q.type === 'spark' ? 0.03 : 0.35
        if (q.t > (q.type === 'spark' ? 50 : 90)) q.dead = true
      }
    }
    this.particles = this.particles.filter((q) => !q.dead)
    for (const b of this.bumps) b.t++
    this.bumps = this.bumps.filter((b) => b.t < 10)
    for (const s of this.popups) s.t++
    this.popups = this.popups.filter((s) => s.t < 45)
    if (this.flash > 0) this.flash--
  }

  updateCamera(snap) {
    const p = this.player
    const target = Math.max(0, Math.min(p.x - VIEW_W * 0.4, this.widthPx - VIEW_W))
    if (snap || target > this.camX) this.camX = target
  }

  // ---------- drawing ----------
  render() {
    const g = this.g
    g.setTransform(1, 0, 0, 1, 0, 0)
    if (this.state === 'loading') {
      g.fillStyle = '#140d22'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
      this.center('LOADING...', 106, '#ffffff', 2)
      return
    }
    this.drawBackground()
    const cam = Math.round(this.camX)
    g.save()
    g.translate(-cam, 0)
    this.drawDecorations()
    this.drawHouse()
    this.drawFlag()
    this.drawTiles(cam)
    this.drawItems()
    this.drawEnemies()
    if (this.state !== 'title' && this.state !== 'intro') this.drawPlayer()
    this.drawParticles(false)
    for (const s of this.popups) drawText(g, s.text, s.x - textWidth(s.text) / 2, s.y - s.t * 0.6, '#ffffff')
    g.restore()
    this.drawParticles(true)
    if (this.flash > 0 && this.flash % 8 < 4) {
      g.fillStyle = 'rgba(255,240,150,0.25)'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
    }
    if (this.state !== 'title') this.drawHud()
    this.drawOverlay()
  }

  drawBackground() {
    const g = this.g
    const cam = this.camX
    const t = this.theme
    const A = this.art
    const sky = t.sky && t.sky.length ? t.sky : ['#5fb7ff']
    const band = Math.ceil(VIEW_H / sky.length)
    sky.forEach((c, i) => {
      g.fillStyle = c
      g.fillRect(0, i * band, VIEW_W, band)
    })
    if (t.background === 'hills') {
      for (let i = -1; i < 6; i++) {
        const x = Math.round(i * 140 - ((cam * 0.15) % 140))
        g.drawImage(A.cloud, x + 20, 22 + (i % 2) * 18)
        g.drawImage(A.cloud, x + 90, 52 + (i % 3) * 6)
      }
      for (let i = -1; i < 5; i++) {
        const x = Math.round(i * 220 - ((cam * 0.4) % 220))
        g.drawImage(A.hillBig, x, 192 - 50)
        g.drawImage(A.hillSmall, x + 130, 192 - 30)
      }
    } else if (t.background === 'cave') {
      for (let i = -1; i < 8; i++) g.drawImage(A.rock, Math.round(i * 70 - ((cam * 0.3) % 70)), 28 + (i % 2) * 6)
      const [lightCol, lampCol] = t.near
      for (let i = -1; i < 6; i++) {
        const x = Math.round(i * 96 - ((cam * 0.6) % 96)) + 40
        g.globalAlpha = 0.12
        g.fillStyle = lightCol
        g.beginPath()
        g.moveTo(x - 6, 50)
        g.lineTo(x + 18, 50)
        g.lineTo(x + 46, 192)
        g.lineTo(x - 34, 192)
        g.fill()
        g.globalAlpha = 1
        g.fillStyle = '#2b2440'
        g.fillRect(x + 5, 32, 2, 14)
        g.fillStyle = lampCol
        g.fillRect(x - 6, 46, 24, 4)
        g.fillStyle = lightCol
        g.fillRect(x - 4, 50, 20, 2)
      }
    } else {
      if (A.stars) {
        for (const [sx, sy, big] of A.stars) {
          const x = Math.round(((sx - cam * 0.05) % 600 + 600) % 600)
          if (x > VIEW_W) continue
          g.fillStyle = (this.frame + sx) % 90 < 80 ? '#ffffff' : '#9aa0c0'
          g.fillRect(x, sy, big ? 2 : 1, big ? 2 : 1)
        }
      }
      g.drawImage(A.sun, (t.background === 'night' ? 320 : 290) - Math.round(cam * 0.03), t.background === 'night' ? 30 : 104)
      for (let i = -1; i < 5; i++) g.drawImage(A.far, Math.round(i * 150 - ((cam * 0.2) % 150)), 102)
      for (let i = -1; i < 5; i++) g.drawImage(A.near, Math.round(i * 130 - ((cam * 0.45) % 130)) + 40, 128)
    }
  }

  drawTiles(cam) {
    const g = this.g
    const T = this.art.tiles
    const x0 = Math.floor(cam / TILE)
    const x1 = Math.min(this.level.width - 1, x0 + Math.ceil(VIEW_W / TILE) + 1)
    const blockFrame = Math.floor(this.frame / 10) % 4
    for (let ty = 0; ty < ROWS; ty++) {
      for (let tx = x0; tx <= x1; tx++) {
        const t = this.tiles[ty][tx]
        if (t === '.') continue
        let img
        switch (t) {
          case '#': img = this.solid(tx, ty - 1) ? T.ground : T.groundTop; break
          case 'B': img = T.brick; break
          case '?': case 'P': img = T.block[blockFrame]; break
          case 'U': img = T.used; break
          case 'S': img = T.stone; break
          case '[': img = T.pipeTL; break
          case ']': img = T.pipeTR; break
          case '{': img = T.pipeBL; break
          case '}': img = T.pipeBR; break
          default: continue
        }
        const bump = this.bumps.find((b) => b.tx === tx && b.ty === ty)
        const off = bump ? -Math.round(Math.sin((bump.t / 10) * Math.PI) * 5) : 0
        g.drawImage(img, tx * TILE, ty * TILE + off)
      }
    }
  }

  drawDecorations() {
    const img = this.art.deco
    for (const x of this.level.decorations) {
      const px = x * TILE
      if (px < this.camX - 48 || px > this.camX + VIEW_W) continue
      const sway = this.theme.decoration === 'plant' ? Math.round(Math.sin(this.frame * 0.03 + x)) : 0
      this.g.drawImage(img, px + sway, 12 * TILE - img.height)
    }
  }

  drawHouse() {
    const x = this.level.houseX * TILE
    if (x > this.camX + VIEW_W || x + 80 < this.camX) return
    this.g.drawImage(this.house, x, 12 * TILE - 64)
  }

  drawFlag() {
    const g = this.g
    const x = this.level.flagX * TILE + 7
    if (x > this.camX + VIEW_W + 40 || x < this.camX - 40) return
    g.fillStyle = '#1b1430'
    g.fillRect(x - 1, 2 * TILE - 2, 4, 9 * TILE + 2)
    g.fillStyle = '#d9e3e8'
    g.fillRect(x, 2 * TILE, 2, 9 * TILE)
    g.fillStyle = config.collectible.colors.light
    g.fillRect(x - 2, 2 * TILE - 5, 6, 5)
    const fy = Math.round(this.flagY)
    g.fillStyle = '#1b1430'
    g.fillRect(x - 21, fy - 1, 21, 16)
    g.fillStyle = config.goal.flag
    g.fillRect(x - 20, fy, 20, 14)
    g.drawImage(this.coinImg, x - 16, fy + 2, 11, 10)
  }

  drawItems() {
    const g = this.g
    for (const it of this.items) {
      if (it.x < this.camX - 16 || it.x > this.camX + VIEW_W) continue
      if (it.type === 'coin') {
        const s = Math.abs(Math.cos(this.frame * 0.08 + it.x * 0.1))
        const w = Math.max(2, Math.round(11 * s))
        g.drawImage(this.coinImg, Math.round(it.x + 5 - w / 2), Math.round(it.y), w, 10)
      } else {
        if (this.frame % 6 < 3) {
          g.fillStyle = 'rgba(255,240,150,0.5)'
          g.fillRect(Math.round(it.x) - 2, Math.round(it.y) - 2, 15, 14)
        }
        g.drawImage(this.powerImg, Math.round(it.x), Math.round(it.y))
      }
    }
  }

  drawEnemies() {
    for (const e of this.enemies) {
      if (!e.active) continue
      const dir = e.vx > 0 ? 1 : -1
      if (e.state === 'squashed') {
        if (e.ch.source === 'sheet' && e.ch.anims.knocked_out) e.ch.draw(this.g, 'knocked_out', dir, 0, e.x, e.y, e.w, e.h)
        else e.ch.draw(this.g, 'walk', dir, 0, e.x, e.y, e.w, e.h, { squash: true })
      } else if (e.state === 'flipped') e.ch.draw(this.g, 'walk', dir, 0, e.x, e.y, e.w, e.h, { flipY: true })
      else e.ch.draw(this.g, 'walk', dir, e.t / (e.def.behavior === 'fly' ? 8 : 10), e.x, e.y, e.w, e.h)
    }
  }

  drawPlayer() {
    const p = this.player
    if (p.hidden) return
    if (p.inv > 0 && Math.floor(p.inv / 4) % 2 === 0) return
    const ch = this.chars.player
    const opts = p.powered ? { glow: config.player.glow || '#ffe066' } : {}
    let anim = 'idle'
    let t = 0
    if (this.state === 'dying') anim = ch.source === 'sheet' && ch.anims.knocked_out ? 'knocked_out' : 'jump'
    else if ((!p.onGround && this.state === 'play') || this.state === 'flag') anim = 'jump'
    else if (Math.abs(p.vx) > 0.15) {
      anim = 'walk'
      t = p.anim
    }
    ch.draw(this.g, anim, p.dir, t, p.x, p.y, p.w, p.h, opts)
  }

  drawParticles(screen) {
    const g = this.g
    for (const q of this.particles) {
      if (!!q.screen !== screen) continue
      if (q.type === 'popcoin') {
        const s = Math.abs(Math.cos(q.t * 0.4))
        const w = Math.max(2, Math.round(11 * s))
        g.drawImage(this.coinImg, Math.round(q.x + 5 - w / 2), Math.round(q.y), w, 10)
      } else if (q.type === 'debris') {
        g.drawImage(this.art.tiles.brick, 0, 0, 8, 8, Math.round(q.x), Math.round(q.y), 8, 8)
      } else if (q.type === 'spark') {
        g.fillStyle = q.col
        g.fillRect(Math.round(q.x), Math.round(q.y), 2, 2)
      }
    }
  }

  drawHud() {
    const g = this.g
    const accent = config.collectible.colors.light
    g.fillStyle = 'rgba(20,12,36,0.55)'
    g.fillRect(0, 0, VIEW_W, 17)
    drawText(g, upper(config.player.name).slice(0, 10), 8, 3, accent)
    drawText(g, String(this.score).padStart(6, '0'), 8, 10, '#ffffff')
    g.drawImage(this.coinImg, 100, 3, 9, 9)
    drawText(g, 'x' + String(this.coins).padStart(2, '0'), 112, 6, '#ffffff')
    drawText(g, 'LEVEL', 160, 3, accent)
    drawText(g, `${this.levelIndex + 1}-${upper(LEVELS[this.levelIndex].name)}`.slice(0, 32), 160, 10, '#ffffff')
    drawText(g, 'TIME', 310, 3, accent)
    drawText(g, String(Math.max(0, this.time)).padStart(3, '0'), 310, 10, this.time <= 100 ? '#ff8a7a' : '#ffffff')
    drawText(g, 'LIVES', 356, 3, accent)
    drawText(g, 'x' + this.lives, 356, 10, '#ffffff')
    if (this.audio.muted) drawText(g, 'MUTED', VIEW_W - 26, 20, '#ffffff')
  }

  center(text, y, color = '#ffffff', s = 1) {
    const fit = Math.max(1, Math.min(s, Math.floor((VIEW_W - 16) / Math.max(1, textWidth(text, 1) + 1))))
    drawText(this.g, text, Math.round((VIEW_W - textWidth(text, fit)) / 2), y, color, fit)
  }

  drawOverlay() {
    const g = this.g
    const blink = Math.floor(this.frame / 30) % 2 === 0
    const accent = config.collectible.colors.light
    const words = upper(config.title).split(' ')
    if (this.state === 'title') {
      g.fillStyle = 'rgba(20,12,36,0.25)'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
      if (words.length > 1 && words.join(' ').length > 10) {
        this.center(words.slice(0, Math.ceil(words.length / 2)).join(' '), 30, accent, 4)
        this.center(words.slice(Math.ceil(words.length / 2)).join(' '), 56, '#9be564', 5)
      } else this.center(words.join(' '), 40, accent, 6)
      this.center(upper(config.subtitle), 90, '#ffffff')
      ;(config.story || []).slice(0, 2).forEach((line, i) => this.center(upper(line), 108 + i * 9, '#ffffff'))
      if (blink) this.center('PRESS ENTER TO START', 144, accent, 2)
      this.center('ARROWS MOVE - SPACE JUMP - SHIFT RUN - P PAUSE - M MUTE', 196, '#c9b8e8')
    } else if (this.state === 'intro') {
      g.fillStyle = '#140d22'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
      this.center(`LEVEL ${this.levelIndex + 1}`, 64, accent, 3)
      this.center(upper(LEVELS[this.levelIndex].name), 92, '#9be564', 2)
      const ch = this.chars.player
      ch.draw(g, 'idle', 1, 0, 180, 124, 16, 32, this.powered ? { glow: config.player.glow } : {})
      drawText(g, 'x ' + this.lives, 210, 140, '#ffffff', 2)
      if (this.checkpointReached) this.center('STARTING FROM CHECKPOINT', 180, '#c9b8e8')
    } else if (this.state === 'paused') {
      g.fillStyle = 'rgba(20,12,36,0.6)'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
      this.center('PAUSED', 96, accent, 3)
      this.center('PRESS P TO CONTINUE', 128, '#ffffff')
    } else if (this.state === 'gameover') {
      g.fillStyle = 'rgba(20,12,36,0.85)'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
      this.center('GAME OVER', 80, '#e0483e', 4)
      this.center('SCORE ' + this.score, 120, '#ffffff', 2)
    } else if (this.state === 'win') {
      g.fillStyle = 'rgba(20,12,36,0.55)'
      g.fillRect(0, 0, VIEW_W, VIEW_H)
      const [a, b] = config.winText || ['YOU WIN!', '']
      this.center(upper(a), 60, '#9be564', 3)
      if (b) this.center(upper(b), 92, accent, 2)
      this.center('FINAL SCORE ' + this.score, 116, '#ffffff', 2)
      this.center(upper(config.collectible.name) + ' ' + this.coins, 138, '#ffffff')
    }
  }
}
